<form class="admin-card" method="post" enctype="multipart/form-data">
    <?= csrf_field() ?><input type="hidden" name="action" value="save_settings">
    <div class="card-head"><h2>Logo, Branding & Site Settings</h2><button class="btn btn-primary">Save Settings</button></div>
    <div class="admin-form-grid">
        <fieldset><legend>Branding</legend><label>Site name<input name="site_name" value="<?= e($settings['site_name'] ?? 'AA Packages') ?>"></label><label>Site logo<input name="site_logo" type="file" accept=".png,.jpg,.jpeg,.webp" data-image-preview></label><div class="preview-grid upload-preview" data-preview-box></div><label>Background pattern<input name="background_pattern" type="file" accept=".png,.jpg,.jpeg,.webp"></label><label>Primary color<input name="theme_primary" type="color" value="<?= e($settings['theme_primary'] ?? '#1565C0') ?>"></label><label>Accent color<input name="theme_primary_light" type="color" value="<?= e($settings['theme_primary_light'] ?? '#4FC3F7') ?>"></label><label>Secondary color<input name="theme_secondary" type="color" value="<?= e($settings['theme_secondary'] ?? '#0D47A1') ?>"></label></fieldset>
        <fieldset><legend>Contact</legend><label>Phone<input name="contact_phone" value="<?= e($settings['contact_phone'] ?? '') ?>"></label><label>Email<input type="email" name="contact_email" value="<?= e($settings['contact_email'] ?? '') ?>"></label><label>Postal code<input name="postal_code" value="<?= e($settings['postal_code'] ?? '') ?>"></label><label>Address<textarea name="contact_address"><?= e($settings['contact_address'] ?? '') ?></textarea></label><label>Hours<input name="business_hours" value="<?= e($settings['business_hours'] ?? '') ?>"></label><label>Map embed<textarea name="map_embed"><?= e($settings['map_embed'] ?? '') ?></textarea></label></fieldset>
        <fieldset><legend>Footer</legend><label>About text<textarea name="footer_about"><?= e($settings['footer_about'] ?? '') ?></textarea></label><label>Social links<textarea></textarea></label></fieldset>
    </div>
    <table class="admin-table"><thead><tr><th>Setting Key</th><th>Value</th></tr></thead><tbody><?php foreach ($settingsRows as $row): ?><tr><td><?= e($row['setting_key']) ?></td><td><?= e($row['setting_value']) ?></td></tr><?php endforeach; ?></tbody></table>
</form>
